import java.util.*;

class Solution {
  public String largestMultipleOfThree(int[] digits) {
    int[] count = new int[10];
    int sum = 0;
    for (int d : digits) {
      count[d]++;
      sum += d;
    }
    int remove = sum % 3;
    if (remove != 0 && !removeOne(count, remove)) {
      if (!removeOne(count, 3 - remove) || !removeOne(count, 3 - remove)) return "";
    }
    StringBuilder result = new StringBuilder();
    for (int d = 9; d >= 0; d--) for (int i = 0; i < count[d]; i++) result.append(d);
    return result.length() == 0 ? "" : result.charAt(0) == '0' ? "0" : result.toString();
  }

  private boolean removeOne(int[] count, int remainder) {
    for (int d = remainder == 1 ? 1 : 2; d <= 9; d += 3)
      if (count[d] > 0) {
        count[d]--;
        return true;
      }
    return false;
  }
}
